def findKthNumber(n: int, k: int) -> int:
    def getSteps(current: int, n: int) -> int:
        steps = 0
        next = current + 1
        while current <= n:
            steps += min(n + 1, next) - current
            current *= 10
            next *= 10
        return steps

    current = 1
    k -= 1  # Adjust k to be zero-indexed

    while k > 0:
        steps = getSteps(current, n)
        if steps <= k:
            current += 1
            k -= steps
        else:
            current *= 10
            k -= 1

    return current
